/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        $("input[name=hideChk]").bind("click", function() {
                const chkIndex = $("input[name=hideChk]").index($(this));
                const chk = $("input[name=newChk]").eq(chkIndex);
                const outputOrdNo = $("input[name=outputOrdNo]").eq(chkIndex);
                const originOutNo = $("input[name=originOutNo]").eq(chkIndex);
                if (chk.val() === "Y") {
                    chk.val("N");
                    outputOrdNo.attr("readonly", false);
                    outputOrdNo.val(originOutNo.val());
                    outputOrdNo.css("color", "#343434");
                } else {
                    chk.val("Y");
                    outputOrdNo.attr("readonly", true);
                    outputOrdNo.val("9999999999");
                    outputOrdNo.css("color", "#9e9e9e");
                }
        });
        $("input[name=outputOrdNo]").bind("keyup", async function(event) {
                const obj = $(this);
                if (obj.attr("readonly") === false || obj.attr("readonly") == null || obj.attr("readonly") == null) {
                    if (!(($c.util.getKeyCode(event) >= 48 && $c.util.getKeyCode(event) <= 57) || ($c.util.getKeyCode(event) >= 96 && $c.util.getKeyCode(event) <= 105) || event.keyCode == 35 || event.keyCode == 36 || event.keyCode == 37 || event.keyCode == 39 || event.keyCode == 8 || event.keyCode == 46) && (event.shiftKey === false)) {
                        await $c.win.alert('숫자만 입력하시기 바랍니다.');
                        $(this).val('');
                    }
                }
        });
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf76200.onpageload' }); }
};

/**
 * @method
 * @name scwin.init_loadList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_action). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_ctxDefaults();
        await scwin.init_conds();
        await scwin.init_loadList();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldstf76200.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.grd_relatedLawList_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_relatedLawList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_relatedLawList');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_relatedLawList'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; } /* 수동 전환 필요: clickTr (인자 미해석) */
        if (typeof scwin.openEditRlaw === 'function') { scwin.openEditRlaw(r["sprtRoomNo"]); } else { console.error('[sdd] 행 동작 미정의: scwin.openEditRlaw (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.openEditRlaw'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_relatedLawList.oncellclick' });
    }
};

/**
 * @event
 * @name scwin.btn_openRegisterPop_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_openRegisterPop_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_openRegisterPop_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.openRegisterPop()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf76200.btn_openRegisterPop_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_setOutOrdNo_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_setOutOrdNo_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_setOutOrdNo_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.fn_setOutOrdNo()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf76200.btn_setOutOrdNo_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_setOutOrdNo
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_setOutOrdNo = async function () {
    const sbmOptions = {
        id: "tx_fn_setOutOrdNo",
        method: "post",
        action: "/ods/sprtroom.do?method=checkOrderDupl",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf76200.tx_fn_setOutOrdNo" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_load_list
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/ods/sprtroom.do?method=checkOrderDupl",
        ref: "dma_loadListReq",
        target: "dlt_relatedLawList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf76200.tx_load_list" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
