 * @hidden N
*/
scwin.reload = function () {
    /* sdd-asis-lifecycle:begin fn_reload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.win.setPageFrameSrc($c.win.getFrame(), null);
    /* sdd-asis-lifecycle:end */
};


/**
