    /* sdd-asis-lifecycle:begin fn_openRegisterPop — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const url = "/ods/sprtroom.do?method=registerRelatedLawForm&SCREN_ID=JLDODS76210.jsp&SCREN_PROCES_TP_CD=01";
    $c.frame.CreateDialogFrame("", (function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(url), "관련법규등록", { width: 1200, height: 800 }, {});
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.openEditRlaw
 * @author Inswave
 * @date 2026. 09. 29
 * @param no
 * @returns
 * @hidden N
*/
scwin.openEditRlaw = function (no) {
    /* sdd-asis-lifecycle:begin fn_openEditRlaw — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const url = "/ods/sprtroom.do?method=readNoticeDetail&sprtRoomNo=" + no + "&sprtRoomId=RLAW&SCREN_ID=JLDODS76220.jsp&SCREN_PROCES_TP_CD=01";
    $c.frame.CreateDialogFrame("", (function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(url), "관련법규변경", { width: 1200, height: 800 }, {});
    /* sdd-asis-lifecycle:end */
};


// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)
scwin.fn_setOutOrdNo = scwin.tx_fn_setOutOrdNo;
